window.docContents[60].resolve({"/Basics/#Logical-Foundations--Basics___-Functional-Programming-in-Lean--Data-and-Functions--Days-of-the-Week-_LPAR_Enumerated-Types_RPAR_":{"contents":"A datatype definition:\n\n\n\ninductive Day : Type where\n  | monday\n  | tuesday\n  | wednesday\n  | thursday\n  | friday\n  | saturday\n  | sunday\ninductive Day : Type where\n  | monday\n  | tuesday\n  | wednesday\n  | thursday\n  | friday\n  | saturday\n  | sunday\ninductive Day : Type where\n  | monday\n  | tuesday\n  | wednesday\n  | thursday\n  | friday\n  | saturday\n  | sunday\n\n\n\n\n\n\nA function on days:\n\ndef nextWorkingDay (d : Day) : Day :=\n  match d with\n  | Day.monday    => Day.tuesday\n  | Day.tuesday   => Day.wednesday\n  | Day.wednesday => Day.thursday\n  | Day.thursday  => Day.friday\n  | Day.friday    => Day.monday\n  | Day.saturday  => Day.monday\n  | Day.sunday    => Day.monday\ndef nextWorkingDay (d : Day) : Day :=\n  match d with\n  | Day.monday    => Day.tuesday\n  | Day.tuesday   => Day.wednesday\n  | Day.wednesday => Day.thursday\n  | Day.thursday  => Day.friday\n  | Day.friday    => Day.monday\n  | Day.saturday  => Day.monday\n  | Day.sunday    => Day.monday\ndef nextWorkingDay (d : Day) : Day :=\n  match d with\n  | Day.monday    => Day.tuesday\n  | Day.tuesday   => Day.wednesday\n  | Day.wednesday => Day.thursday\n  | Day.thursday  => Day.friday\n  | Day.friday    => Day.monday\n  | Day.saturday  => Day.monday\n  | Day.sunday    => Day.monday\n\n\n\n\n\n\nEvaluation:\n\n\n\n#eval nextWorkingDay Day.friday\n#eval nextWorkingDay Day.friday\n#eval nextWorkingDay Day.friday\n\n\nDay.monday\n\n\n#eval nextWorkingDay (nextWorkingDay Day.saturday)\n#eval nextWorkingDay (nextWorkingDay Day.saturday)\n#eval nextWorkingDay (nextWorkingDay Day.saturday)\n\n\nDay.tuesday\n\n\nWe can also record what we expect the result of calling a function to be in the form of a Lean\nexample:\n\nexample : nextWorkingDay (nextWorkingDay Day.saturday) = Day.tuesday := by\n  rfl\nexample : nextWorkingDay (nextWorkingDay Day.saturday) = Day.tuesday := by\n  rfl\nexample : nextWorkingDay (nextWorkingDay Day.saturday) = Day.tuesday := by\n  rfl\n\n\n\n\nThe rfl tactic is used to observe that both sides of an equal sign evaluate to the same value.\n\n","context":"Logical Foundations\u0009Basics: Functional Programming in Lean\u0009Data and Functions","header":"2.1.1. Days of the Week (Enumerated Types)","id":"/Basics/#Logical-Foundations--Basics___-Functional-Programming-in-Lean--Data-and-Functions--Days-of-the-Week-_LPAR_Enumerated-Types_RPAR_"}});